<?php namespace LaraSelector\Tests; use LaraSelector\LaraSelectorMarkupTokenizer; use LaraSelector\LaraSelectorToken; class TokenizerTest extends TestCase { public function test_marks_opening_lines_and_ignores_raw_blocks(): void { $html="<div\n class=\"x\">{{ \$x }}</div><script>const x='<i>';</script>"; $out=LaraSelectorMarkupTokenizer::instrument($html,__DIR__.'/fixtures/sample.blade.php',app(LaraSelectorToken::class)); $this->assertStringContainsString('data-laraselector',$out); $this->assertSame(1,substr_count($out,'data-laraselector')); } }
